import { v4 as uuidv4 } from "uuid";import { environment } from "../config/environment";import { createApiClient } from "./apiClient";const client=createApiClient(environment.api.checkoutServiceUrl);
export async function createCheckout({userId,cardLast4="4242",idempotencyKey}){if(!userId)throw new Error("A development user ID is required.");return (await client.post("/api/v1/checkouts",{userId,idempotencyKey:idempotencyKey||`web-checkout-${uuidv4()}`,cardLast4})).data;}
